import{_ as l,h as s,i as a,c as n,v as r,p,x as t,m as o,e as d,S as h}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"Persistent kernel","description":"","frontmatter":{"title":"Persistent kernel","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/persistent-kernel.md","filePath":"llm/persistent-kernel.md","lastUpdated":1788454257000}'),A={name:"llm/persistent-kernel.md"};function c(m,e,C,M,T,S){const i=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="persistent-kernel" tabindex="-1">Persistent kernel <a class="header-anchor" href="#persistent-kernel" aria-label="Permalink to &quot;Persistent kernel&quot;">​</a></h1><div class="epigraph"><p>让 CTA 在 SM 上住下来，自己从设备侧队列取下一块工作，而不是每块 GEMM 由主机再 launch 一次：省掉的是核间排水与启动，不是单块内部的 MMA。</p><footer>—— NVIDIA CUTLASS 持久化调度 / CUDA 占用率模型，对照 Hopper 白皮书中的异步流水</footer></div><p>默认执行模型里，每个 kernel 启动对应一批 CTA，跑完即走，SM 流水线排空，下一次启动再填满。短核密集时，排水与启动的间隙可见；即使用 <a href="/llm/cuda-graph-infer">CUDA Graph</a> 把启动收成一次，图中相邻节点仍是两次独立的核，中间仍可能丢占用。Persistent kernel 把网格做成大约「占满 SM」的常驻 CTA，内层循环从工作队列（下一 tile、下一层、下一请求的一块 GEMM）取活，直到队列空。CUTLASS 的 persistent / stream-K 调度、部分推理引擎的 decode 循环，都在这一模型里。</p><p>本篇写何时该常驻、工作如何分发、以及和 Graph、融合的分工。不编造未公开的 SM 排水周期数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 的吞吐建立在延迟隐藏上：足够多的 CTA / warp 在等内存时切出去做别的。核一结束，这些现场消失，下核再从零填指令缓存、记分牌和流水线。若每个核只做一小块工作（decode 的瘦 GEMM、一层里拆开的 RMSNorm），填满—排空的占空比变差。融合能把小核合成大核，但融合有数值与编译边界；Graph 能减 CPU 提交，但不保证 GPU 侧两个节点之间不断流。持久化要回答的是：能否让同一批 CTA 跨过「逻辑上的多个任务」保持占用。</p><p>代价同样真实。常驻 CTA 把 SM 占住，若队列短暂空闲，别的流上的核进不来，延迟尾部变差。工作分发若在设备上抢队列，原子争用会成为新瓶颈。问题是占用与公平、以及队列粒度，不是「常驻一定更快」。</p><h3 id="与-grid-stride-循环的差别" tabindex="-1">与 grid-stride 循环的差别 <a class="header-anchor" href="#与-grid-stride-循环的差别" aria-label="Permalink to &quot;与 grid-stride 循环的差别&quot;">​</a></h3><p>Grid-stride 是一个核内：CTA 用 <code>blockIdx + gridDim</code> 的步长扫完所有 tile，扫完核结束。它减少启动次数，但网格大小通常仍按 tile 数来，可能远超 SM 数，调度器靠过量 CTA 做切换。持久化把网格钉在「每 SM 一到数个 CTA」，循环条件是队列非空而不是「我的 stride 走完」。长时间驻留、跨多次逻辑 GEMM、甚至跨层，才是 persistent 这一词在 CUTLASS 与推理文献里的意思。二者都是「少启动」，粒度不同。</p><p><span class="marginnote">主机侧 <code>while</code> 里反复 launch 同一核，即使核很小，也不是持久化。持久化的判定是：设备上的 CTA 在一次 launch 里消费了多次逻辑工作项。Nsight Systems 上应看到一次很长的核，而不是一排同名短核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上通常有三件套。</p><p><strong>占用目标</strong>：grid 取 <code>sm_count × cta_per_sm</code>，<code>cta_per_sm</code> 由寄存器与 smem 反推，保证常驻而不过度超订。超订在持久化里帮助变小——反正 CTA 不退出，多余的 CTA 只是排队等 SM，浪费队列里的工作项编号。</p><p><strong>工作队列</strong>：可以是全局内存里的原子计数器（下一个 tile ID）、按层预排好的静态表、或 Hopper 上与 TMA 描述符列表结合的「下一盒子」。Stream-K 一类调度把 \\(K\\) 维切给不同 CTA 再规约，也常落在持久化 CTA 上：CTA 跑完自己的 K 片段后去取下一项，而不是结束核。</p><p><strong>退出条件</strong>：队列空、或主机写入的停止标志。推理 decode 可以把「一整步的所有层」放进一次持久核，层间不退 SM；也可以每层一个持久核，由 Graph 串起来。前者占用最好，但要把一整步的控制流写进同一核，MoE 与变长很难。后者更模块化，排水发生在层边界。</p>',15)),(a(),p(h,null,{default:t(()=>[d(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%B8%BB%E6%9C%BA%20launch%20%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20CTA%5B%22CTA%20%E5%8D%A0%E6%BB%A1%20SM%22%5D%0A%20%20CTA%20--%3E%20Q%7B%22%E8%AE%BE%E5%A4%87%E9%98%9F%E5%88%97%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%96%E4%B8%8B%E4%B8%80%20tile%20%2F%20%E4%B8%8B%E4%B8%80%E5%B1%82%22%7C%20WORK%5B%22TMA%20%2B%20MMA%20%2B%20epilogue%22%5D%0A%20%20WORK%20--%3E%20Q%0A%20%20Q%20--%3E%7C%22%E7%A9%BA%20%2F%20%E5%81%9C%E6%AD%A2%E6%A0%87%E5%BF%97%22%7C%20END%5B%22%E6%A0%B8%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="与-warp-特化、流水的组合" tabindex="-1">与 warp 特化、流水的组合 <a class="header-anchor" href="#与-warp-特化、流水的组合" aria-label="Permalink to &quot;与 warp 特化、流水的组合&quot;">​</a></h3><p>Hopper 上持久化 CTA 内部往往仍是 <a href="/llm/warp-specialization">warp 特化</a> 加 <a href="/llm/sw-pipeline-buffer">软件流水</a>：常驻解决的是<strong>工作项之间</strong>不断流，特化解决的是<strong>一项内部</strong>拷贝与 MMA 重叠。不要用持久化替代 TMA 流水——队列再快，块内若同步搬砖，屋顶线还在。CUTLASS 3.x 的 Hopper 主循环把三者做成可组合的 kernel adapter：调度器（persistent 与否）在核入口，集体主循环在内层。</p><p>服务侧还要考虑与连续批处理的接口。若每步 batch 形状变，持久核必须能从固定缓冲读到当前形状，或在步边界结束核、下一步再 launch。把「永远不退出的核」和「每步换拓扑」绑在一起，会把动态调度全部塞进设备侧，调试成本通常高于收益。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收益来自保持 SM 的热状态：指令缓存、MMA 流水、已经填好的 pipeline stage、以及（在允许时）不重复做的预热拷贝。对短工作项，这些固定成本被摊到多次消费上。对已经很长的 prefill GEMM，一次核已经占满墙钟，持久化几乎无增益，甚至因调度器少了灵活超订而略差。</p><p>正确性依赖于工作项划分无重叠、规约有明确所有者。Stream-K 的部分和要写到指定缓冲再做一次归约核或核内协作归约；持久化不自动处理这部分。原子队列要避免所有 CTA 打同一 cache line：可以用每 SM 私有的工作范围，或条带化 tile 编号。争用严重时，持久化的墙钟会差过「普通网格一次 launch」。</p><p><span class="marginnote">持久核把 GPU 变成一台拉模型的工作机，主机变成填队列的生产者。CPU 若填得比消费慢，SM 空转在轮询上，功耗与延迟都差。队列项应足够粗（一整块 GEMM tile 或一整层），不要按标量任务投喂。</span></p><h3 id="和-cuda-graph-怎么选" tabindex="-1">和 CUDA Graph 怎么选 <a class="header-anchor" href="#和-cuda-graph-怎么选" aria-label="Permalink to &quot;和 CUDA Graph 怎么选&quot;">​</a></h3><p>Graph：拓扑固定、多个<strong>不同</strong>核、要减 CPU 提交。Persistent：同一套 CTA 代码、多个<strong>同类</strong>工作项、要减 GPU 排水。Decode 一步若是「RMSNorm 核 + GEMM 核 + 注意力核」三种代码，Graph 更自然；若已融合成一个大核反复吃层，持久化更自然。二者可叠：Graph 的一个节点是持久核。先用 profiler 看间隙在 CPU launch 还是在 GPU 核间空闲，再加其中一个，避免两套状态机同时上。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在多租户 MPS 上默认常驻占满 SM，除非理解对邻居延迟的影响，见 <a href="/llm/mps-mig">MPS 与 MIG</a>。不要让持久核内出现可阻塞的设备侧等待（无超时地等主机旗标），否则整卡卡死难以取消。不要把 NCCL 调用塞进持久循环却不核对图/流语义。取消与超时应走主机停止标志 + 有限轮询间隔，并在文档里写清最坏唤醒时间。</p><p>占用计算要用实际寄存器与 smem，含 pipeline stage。复制 CUTLASS 示例的 grid 到自己更大的 tile 上，可能每 SM 驻不下，网格空转。数值上，持久化改变 tile 被处理的顺序（尤其 stream-K），浮点尾差会变，应对照非持久路径设容差。</p><p><span class="marginnote">出处：CUTLASS 文档的 persistent CTA / stream-K 调度；CUDA Occupancy 与 launch 配置；Hopper 白皮书提供异步主循环为何值得跨 tile 保持常驻。CUDA Graph 指南说明二者解决的提交层不同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Persistent kernel 用常驻 CTA 从设备队列拉多次工作，减少核间排水与重复启动。</li><li>与 grid-stride 的差别是网格钉在 SM 占用上，循环跨逻辑任务而不是一次扫完就退出。</li><li>适合短而重复的同类工作；大 prefill GEMM 与高度动态的拓扑收益有限。</li><li>块内仍要靠 TMA / WGMMA / 流水打屋顶线；持久化不替代融合。</li><li>与 Graph 按瓶颈选择或叠加；注意多租户占用与取消语义。</li><li>出处：CUTLASS 持久化调度与 CUDA 占用率模型。</li></ul>',15))])}const g=l(A,[["render",c]]);export{u as __pageData,g as default};
